function isPalindrome(originalString) {
  const cleanedString = originalString.toLowerCase().replace(/[^a-z0-9]/g, '');
  const stringLength = cleanedString.length;

  for (let i = 0; i < Math.floor(stringLength / 2); i++) {
    const charFromStart = cleanedString[i];
    const charFromEnd = cleanedString[stringLength - 1 - i];

    if (`${charFromStart}` !== `${charFromEnd}`) {
      console.log(`Mismatch detected: ${charFromStart} vs ${charFromEnd} at index ${i}`);
      return false;
    }
  }
  const resultMessage = `The string '${originalString}' is a palindrome.`;
  console.log(resultMessage);
  return true;
}

const test1 = 'Racecar';
const test2 = 'hello world';
const test3 = 'A man, a plan, a canal: Panama';
const test4 = 'No lemon, no melon';

isPalindrome(`${test1}`);
isPalindrome(`${test2}`);
isPalindrome(`${test3}`);
isPalindrome(`${test4}`);
isPalindrome(`123${321}`);
isPalindrome(`My string is ${'not'} a palindrome.`);

