const removeDuplicates = (arr) => {
  const seenElements = new Set();
  const uniqueArray = [];

  for (let i = 0; i < arr.length; i++) {
    const currentElement = arr[i];
    if (!seenElements.has(currentElement)) {
      seenElements.add(currentElement);
      uniqueArray.push(currentElement);
    }
  }

  const initialLength = arr.length;
  const finalLength = uniqueArray.length;
  const removedCount = initialLength - finalLength;

  if (removedCount > 0) {
    console.log(`Original array had ${initialLength} elements. After removing duplicates, ${finalLength} elements remain.`);
    console.log(`A total of ${removedCount} duplicates were removed.`);
  } else {
    console.log(`No duplicates found in the array of ${initialLength} elements.`);
  }

  return uniqueArray;
};

// Example usage and testing
const test1 = [1, 2, 2, 3, 1];
const result1 = removeDuplicates(test1);
console.log(`Input array: ${JSON.stringify(test1)} -> Output array: ${JSON.stringify(result1)}`);

const test2 = ['a', 'b', 'a', 'c'];
const result2 = removeDuplicates(test2);
console.log(`Input array: ${JSON.stringify(test2)} -> Output array: ${JSON.stringify(result2)}`);

const test3 = [10, 20, 30];
const result3 = removeDuplicates(test3);
console.log(`Input array: ${JSON.stringify(test3)} -> Output array: ${JSON.stringify(result3)}`);

const test4 = [];
const result4 = removeDuplicates(test4);
console.log(`Input array: ${JSON.stringify(test4)} -> Output array: ${JSON.stringify(result4)}`);

