const simpleCalculator = (num1, operator, num2) => {
  let result;

  switch (operator) {
    case '+':
      result = num1 + num2;
      break;
    case '-':
      result = num1 - num2;
      break;
    case '*':
      result = num1 * num2;
      break;
    case '/':
      if (num2 === 0) {
        console.warn(`Division by zero attempted for: ${num1} ${operator} ${num2}`);
        return null;
      }
      result = num1 / num2;
      break;
    default:
      console.error(`Invalid operator provided: "${operator}". Expected one of +, -, *, /.`);
      return null;
  }

  const operationString = `${num1} ${operator} ${num2}`;
  console.log(`Performing operation: ${operationString}`);

  if (result === null) {
    console.error(`Failed to calculate for expression: ${operationString}`);
  } else {
    console.info(`The result of ${num1} ${operator} ${num2} is ${result}.`);
  }

  const finalOutputMessage = `Calculation complete for ${operator} operation.`;
  console.log(finalOutputMessage);

  return result;
};

