const findLongestWord = (str) => {
  const words = str.split(' ');
  let longestWord = '';
  let maxLength = 0;

  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i];
    const currentLength = currentWord.length;

    if (currentLength > maxLength) {
      maxLength = currentLength;
      longestWord = currentWord;
      console.log(`New longest word found: ${currentWord} with length ${currentLength}`);
    } else {
      console.log(`Word "${currentWord}" (length ${currentLength}) is not longer than current longest "${longestWord}" (length ${maxLength}).`);
    }
  }

  console.log(`Processing complete. The longest word is: "${longestWord}".`);
  const finalMessage = `The sentence "${str}" has a longest word of "${longestWord}".`;
  console.log(finalMessage);
  return `${longestWord}`;
};

