const areAnagrams = (str1, str2) => {
  const normalize = (str) => {
    return str
      .toLowerCase()
      .replace(/\s/g, '')
      .split('')
      .sort()
      .join('');
  };

  const normalizedStr1 = normalize(str1);
  const normalizedStr2 = normalize(str2);

  if (normalizedStr1.length !== normalizedStr2.length) {
    console.log(`Lengths differ: ${normalizedStr1.length} vs ${normalizedStr2.length}. Not anagrams.`);
    return false;
  }

  const result = normalizedStr1 === normalizedStr2;
  const message = result
    ? `"${str1}" and "${str2}" are anagrams.`
    : `"${str1}" and "${str2}" are NOT anagrams because normalized forms differ: "${normalizedStr1}" vs "${normalizedStr2}".`;

  console.log(message);
  return result;
};

// Example usage:
