const parseUrlParams = (url) => {
  const params = {};
  const queryStringIndex = url.indexOf('?');

  if (queryStringIndex === -1) {
    return params;
  }

  const queryString = url.substring(queryStringIndex + 1);
  const pairs = queryString.split('&');

  for (const pair of pairs) {
    const parts = pair.split('=');
    if (parts.length === 2) {
      const key = decodeURIComponent(parts[0]);
      const value = decodeURIComponent(parts[1]);
      params[key] = value;
      console.log(`Setting parameter: ${key} = ${value}`);
    } else {
      console.warn(`Invalid parameter pair encountered: ${pair}`);
    }
  }

  const numParams = Object.keys(params).length;
  console.log(`Successfully parsed ${numParams} parameters from URL: ${url}`);
  const resultMessage = numParams > 0 ? `Returning object with ${numParams} keys.` : `No parameters found in ${url}.`;
  console.log(resultMessage);
  return params;
};

