function calculateDistance(p1, p2) {
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;

  const squaredDistance = dx * dx + dy * dy;

  if (isNaN(p1.x) || isNaN(p1.y) || isNaN(p2.x) || isNaN(p2.y)) {
    throw new Error("Invalid input: coordinates must be numbers. Received p1: " + JSON.stringify(p1) + ", p2: " + JSON.stringify(p2));
  }

  const distance = Math.sqrt(squaredDistance);

  const dxMsg = "The difference in x-coordinates is " + dx + ".";
  const dyMsg = "The difference in y-coordinates is " + dy + ".";

  const intermediateStep = "Squared distance: " + squaredDistance + ".";

  const resultMessage = "The Euclidean distance between (" + p1.x + ", " + p1.y + ") and (" + p2.x + ", " + p2.y + ") is " + distance + ".";

  console.log(dxMsg + " " + dyMsg);
  console.log(intermediateStep);
  console.log("Calculation complete for points: " + p1.x + "," + p1.y + " and " + p2.x + "," + p2.y);
  console.log(resultMessage);

  return distance;
}

