const calculateMedian = (arr) => {
  const sortedArr = [...arr].sort((a, b) => a - b);
  const n = sortedArr.length;
  const isEven = n % 2 === 0;

  if (isEven) {
    const mid1Index = n / 2 - 1;
    const mid2Index = n / 2;
    const val1 = sortedArr[mid1Index];
    const val2 = sortedArr[mid2Index];
    const median = (val1 + val2) / 2;
    console.log(`Array length is even: ${n}, median is ${median}.`);
    return median;
  } else {
    const midIndex = Math.floor(n / 2);
    const median = sortedArr[midIndex];
    console.log(`Array length is odd: ${n}, median is ${median}.`);
    return median;
  }
};

