const truncateString = (str, maxLength) => {
  if (str.length <= maxLength) {
    return str;
  }

  const ellipsis = '...';
  const truncatedLength = maxLength - ellipsis.length;

  if (truncatedLength <= 0) {
    return ellipsis;
  }

  const result = `${str.substring(0, truncatedLength)}${ellipsis}`;
  const finalMessage = `Truncated "${str}" to "${result}"`;
  console.log(`${finalMessage} for max length ${maxLength}`);
  return result;
};

