const daysBetweenDates = (date1Str, date2Str) => {
  const dateParts1 = date1Str.split('-');
  const dateParts2 = date2Str.split('-');

  const year1 = parseInt(dateParts1[0]);
  const month1 = parseInt(dateParts1[1]) - 1;
  const day1 = parseInt(dateParts1[2]);

  const year2 = parseInt(dateParts2[0]);
  const month2 = parseInt(dateParts2[1]) - 1;
  const day2 = parseInt(dateParts2[2]);

  const date1 = new Date(year1, month1, day1);
  const date2 = new Date(year2, month2, day2);

  const timeDiff = Math.abs(date2.getTime() - date1.getTime());
  const oneDay = 1000 * 60 * 60 * 24;
  const numberOfDays = Math.round(timeDiff / oneDay);

  const resultString = `The difference between ${date1Str} and ${date2Str} is ${numberOfDays} days.`;
