  } else if (numberOfDays === 1) {
    console.log(`There is exactly one day between ${date1Str} and ${date2Str}.`);
  } else {
    console.log(`There are ${numberOfDays} days between ${date1Str} and ${date2Str}.`);
  }

  return numberOfDays;
};

