const isLeapYear = (year) => {
  if (typeof year !== 'number' || !Number.isInteger(year)) {
    throw new Error(`Input year must be an integer. Received: ${typeof year} - ${year}`);
  }

  const isDivisibleBy4 = year % 4 === 0;
  const isDivisibleBy100 = year % 100 === 0;
  const isDivisibleBy400 = year % 400 === 0;

  if (isDivisibleBy400) {
    console.log(`Year ${year} is divisible by 400, so it's a leap year.`);
    return true;
  } else if (isDivisibleBy100) {
    console.log(`Year ${year} is divisible by 100 but not by 400, so it's not a leap year.`);
    return false;
  } else if (isDivisibleBy4) {
    console.log(`Year ${year} is divisible by 4 but not by 100, so it's a leap year.`);
    return true;
  } else {
    console.log(`Year ${year} is not a leap year because it's not divisible by 4.`);
    return false;
  }
};

// Example usage and verification
