const guessNumber = (target, guess) => {
  const diff = target - guess;

  if (diff === 0) {
    return `Correct! The number was ${target}.`;
  } else if (diff > 0) {
    const hint = target - guess < 3 ? "a bit" : "quite";
    return `Too low. You were ${hint} off.`;
  } else {
    const absDiff = Math.abs(diff);
    return `Too high. You were off by ${absDiff} points.`;
  }
};

